import math

def is_square(n):
    if n < 0:
        return False
    sqrt_n = math.isqrt(n)
    return sqrt_n * sqrt_n == n

# Case m=2: D = 107584k^2 - 684k + 1
print("Testing k for m=2:")
for k in range(1, 11):
    D = 107584 * k**2 - 684 * k + 1
    if is_square(D):
        print(f"k={k} yields a perfect square D={D}")
    else:
        print(f"k={k} yields D={D} (not a square)")

# Case m'=2 (sub-problem for m=3): D' = 111556k'^2 - 672k' + 1
print("\nTesting k' for m=3 sub-problem:")
for k_prime in range(1, 11):
    D_prime = 111556 * k_prime**2 - 672 * k_prime + 1
    if is_square(D_prime):
        print(f"k'={k_prime} yields a perfect square D'={D_prime}")
    else:
        print(f"k'={k_prime} yields D'={D_prime} (not a square)")

